# EVOLVE-BLOCK-START
import networkx as nx
import json
import os
import pandas as pd
from typing import Dict, List


def search_algorithm(src, dsts, G, num_partitions):
    """Build a capacity-feasible partition-aware broadcast topology with a MILP.

    Each destination-partition is an integral commodity.  Binary edge-install
    variables preserve the shared-edge broadcast cost model, while binary
    commodity variables allow partitions to use separate parallel routes.
    Simultaneous partition traffic is constrained by each link throughput.
    """
    topology = BroadCastTopology(src, dsts, num_partitions)
    h = G.copy()
    h.remove_edges_from(list(h.in_edges(src)) + list(nx.selfloop_edges(h)))
    h.remove_edges_from([
        (u, v) for u, v, data in h.edges(data=True)
        if data.get("cost") is None or data.get("cost") != data.get("cost")
        or data.get("cost") < 0 or data.get("throughput", 0) is None
        or data.get("throughput", 0) <= 0
    ])

    terminals = list(dict.fromkeys(d for d in dsts if d != src))
    reachable = [d for d in terminals if src in h and d in h and nx.has_path(h, src, d)]
    if not terminals:
        for dst in dsts:
            for part in range(num_partitions):
                topology.set_dst_partition_paths(dst, part, [])
        return topology

    # A partition represents an equal share of one destination's input stream.
    # This keeps aggregate demand per receiver equal to one throughput unit.
    demand = 1.0 / max(int(num_partitions), 1)
    commodities = [(dst, part) for dst in reachable for part in range(num_partitions)]
    edges = list(h.edges())
    paths = {}
    solved = False

    if edges and commodities:
        try:
            import numpy as np
            from scipy.optimize import Bounds, LinearConstraint, milp
            from scipy.sparse import lil_matrix

            nodes = list(h.nodes())
            m, q = len(edges), len(commodities)
            outgoing = {v: [] for v in nodes}
            incoming = {v: [] for v in nodes}
            for ei, (u, v) in enumerate(edges):
                outgoing[u].append(ei)
                incoming[v].append(ei)

            # flow conservation, x<=installed, and one aggregate capacity row
            # per edge. x variables are integral so every output is a real path.
            rows = q * len(nodes) + q * m + m
            A = lil_matrix((rows, m + q * m), dtype=float)
            lo, hi = np.empty(rows), np.empty(rows)
            row = 0
            for ci, (dst, _) in enumerate(commodities):
                offset = m + ci * m
                for node in nodes:
                    for ei in outgoing[node]:
                        A[row, offset + ei] = 1
                    for ei in incoming[node]:
                        A[row, offset + ei] = -1
                    value = 1 if node == src else -1 if node == dst else 0
                    lo[row] = hi[row] = value
                    row += 1
                for ei in range(m):
                    A[row, offset + ei] = 1
                    A[row, ei] = -1
                    lo[row], hi[row] = -np.inf, 0
                    row += 1

            for ei, (u, v) in enumerate(edges):
                for ci in range(q):
                    A[row, m + ci * m + ei] = demand
                lo[row] = -np.inf
                hi[row] = float(h[u][v]["throughput"])
                row += 1

            install_cost = [
                float(h[u][v]["cost"]) +
                1e-9 / max(float(h[u][v]["throughput"]), 1e-12)
                for u, v in edges
            ]
            # The tiny routing term eliminates gratuitous cycles without
            # changing any meaningful installation-cost decision.
            objective = np.array(install_cost + [1e-12] * (q * m))
            result = milp(
                c=objective,
                integrality=np.ones(m + q * m),
                bounds=Bounds(np.zeros(m + q * m), np.ones(m + q * m)),
                constraints=LinearConstraint(A.tocsr(), lo, hi),
                options={"time_limit": 25.0, "mip_rel_gap": 0.0},
            )

            if result.x is not None:
                for ci, (dst, part) in enumerate(commodities):
                    subgraph = nx.DiGraph()
                    offset = m + ci * m
                    subgraph.add_edges_from(
                        edges[ei] for ei in range(m) if result.x[offset + ei] > 0.5
                    )
                    try:
                        node_path = nx.shortest_path(subgraph, src, dst)
                        paths[(dst, part)] = [
                            [u, v, G[u][v]] for u, v in zip(node_path, node_path[1:])
                        ]
                    except (nx.NetworkXNoPath, nx.NodeNotFound):
                        paths = {}
                        break
                solved = len(paths) == len(commodities)
        except (ImportError, ValueError, RuntimeError):
            solved = False

    # Preserve robust behavior if capacities make the model infeasible or a
    # solver is unavailable: use independent least-cost paths.
    for dst in dsts:
        for part in range(num_partitions):
            if dst == src:
                path_edges = []
            elif solved and (dst, part) in paths:
                path_edges = paths[(dst, part)]
            else:
                try:
                    node_path = nx.dijkstra_path(h, src, dst, weight="cost")
                    path_edges = [[u, v, G[u][v]] for u, v in zip(node_path, node_path[1:])]
                except (nx.NetworkXNoPath, nx.NodeNotFound):
                    continue
            topology.set_dst_partition_paths(dst, part, list(path_edges))

    return topology


class SingleDstPath(Dict):
    partition: int
    edges: List[List]  # [[src, dst, edge data]]


class BroadCastTopology:
    def __init__(self, src: str, dsts: List[str], num_partitions: int = 4, paths: Dict[str, SingleDstPath] = None):
        self.src = src  # single str
        self.dsts = dsts  # list of strs
        self.num_partitions = num_partitions

        # dict(dst) --> dict(partition) --> list(nx.edges)
        # example: {dst1: {partition1: [src->node1, node1->dst1], partition 2: [src->dst1]}}
        if paths is not None:
            self.paths = paths
            self.set_graph()
        else:
            self.paths = {dst: {str(i): None for i in range(num_partitions)} for dst in dsts}

    def get_paths(self):
        print(f"now the set path is: {self.paths}")
        return self.paths

    def set_num_partitions(self, num_partitions: int):
        self.num_partitions = num_partitions

    def set_dst_partition_paths(self, dst: str, partition: int, paths: List[List]):
        """
        Set paths for partition = partition to reach dst
        """
        partition = str(partition)
        self.paths[dst][partition] = paths

    def append_dst_partition_path(self, dst: str, partition: int, path: List):
        """
        Append path for partition = partition to reach dst
        """
        partition = str(partition)
        if self.paths[dst][partition] is None:
            self.paths[dst][partition] = []
        self.paths[dst][partition].append(path)

def make_nx_graph(cost_path=None, throughput_path=None, num_vms=1):
    """
    Default graph with capacity constraints and cost info
    nodes: regions, edges: links
    per edge:
        throughput: max tput achievable (gbps)
        cost: $/GB
        flow: actual flow (gbps), must be < throughput, default = 0
    """
    # Use relative path from this file's location
    current_dir = os.path.dirname(os.path.abspath(__file__))

    if cost_path is None:
        cost = pd.read_csv(os.path.join(current_dir, "profiles/cost.csv"))
    else:
        cost = pd.read_csv(cost_path)

    if throughput_path is None:
        throughput = pd.read_csv(os.path.join(current_dir, "profiles/throughput.csv"))
    else:
        throughput = pd.read_csv(throughput_path)

    G = nx.DiGraph()
    for _, row in throughput.iterrows():
        if row["src_region"] == row["dst_region"]:
            continue
        G.add_edge(row["src_region"], row["dst_region"], cost=None, throughput=num_vms * row["throughput_sent"] / 1e9)

    for _, row in cost.iterrows():
        if row["src"] in G and row["dest"] in G[row["src"]]:
            G[row["src"]][row["dest"]]["cost"] = row["cost"]

    # some pairs not in the cost grid
    no_cost_pairs = []
    for edge in G.edges.data():
        src, dst = edge[0], edge[1]
        if edge[-1]["cost"] is None:
            no_cost_pairs.append((src, dst))
    print("Unable to get costs for: ", no_cost_pairs)

    return G


